const SEAL_SRC = 'data:image/jpeg;base64,';
function loadImg(src) { const im = new Image(); im.src = src; return im; }
function photo(g, im, x, y, w, h, zoom, alpha) {   // cover-fit photo with slow Ken Burns zoom
  if (!im.complete || !im.naturalWidth) return; g.save(); g.globalAlpha = alpha; g.beginPath(); g.rect(x, y, w, h); g.clip();
  const r = Math.max(w / im.naturalWidth, h / im.naturalHeight) * zoom, iw = im.naturalWidth * r, ih = im.naturalHeight * r; g.drawImage(im, x + (w - iw) / 2, y + (h - ih) / 2, iw, ih); g.restore(); }
function credit(g, txt) { g.font = '600 20px Inter'; g.textAlign = 'right'; g.fillStyle = 'rgba(255,255,255,0.55)'; g.fillText(txt, W - 24, H * 0.205); }
const c = makeCanvas(), g = c.getContext('2d');
const SEAL = loadImg(SEAL_SRC);
window.renderFrame = function (t) { const k = clamp(t / DURATION), a = ease.out(clamp((k - 0.45) / 0.2));
  g.fillStyle = '#100c08'; g.fillRect(0, 0, W, H); g.fillStyle = '#c9a25a'; g.beginPath(); g.roundRect(W * 0.08 - 10, H * 0.22 - 10, W * 0.84 + 20, W * 0.63 + 20, 22); g.fill();
  photo(g, SEAL, W * 0.08, H * 0.22, W * 0.84, W * 0.63, 1.0 + 0.12 * ease.inOut(k), 1);
  g.save(); g.globalAlpha = a; g.font = '800 40px Inter'; g.textAlign = 'center';
  for (const [x, txt, col] of [[W * 0.28, 'ALI RAJA', '#38BDF8'], [W * 0.72, 'ARAKKAL BEEVI', '#F472B6']]) { g.fillStyle = 'rgba(10,8,6,0.85)'; g.beginPath(); g.roundRect(x - 190, H * 0.62, 380, 78, 39); g.fill(); g.strokeStyle = col; g.lineWidth = 4; g.stroke(); g.fillStyle = col; g.fillText(txt, x, H * 0.62 + 52); }
  g.restore(); credit(g, "Photo: Shijaz / Wikimedia Commons, CC BY-SA 3.0"); SK.grain(g, t, 0.04); };